using System;
using System.Globalization;
using System.Web;

namespace InformationWeb.Controls.Ethic
{
    /// <summary>
    /// Đọc điểm tự đánh giá từ Request.Form theo QuestionID — ổn định với Repeater lồng nhau (ctl00).
    /// </summary>
    public static class EthicFormPostHelper
    {
        public static bool TryGetPostedMarkByQuestionId(HttpRequest request, int questionId, out decimal mark, out string markText)
        {
            mark = 0;
            markText = string.Empty;

            if (request == null || request.Form == null || questionId <= 0)
                return false;

            string questionIdValue = questionId.ToString();
            string rowPrefix = FindRowPrefixByHiddenField(request, "hidQuestionID", questionIdValue);

            if (string.IsNullOrEmpty(rowPrefix))
                rowPrefix = FindRowPrefixByHiddenField(request, "hidEthicQuestionID", questionIdValue);

            if (string.IsNullOrEmpty(rowPrefix))
                return false;

            foreach (string key in request.Form.AllKeys)
            {
                if (string.IsNullOrEmpty(key))
                    continue;

                if (key.IndexOf(rowPrefix) != 0)
                    continue;

                if (key.IndexOf("txtValue") < 0)
                    continue;

                string value = request.Form[key];
                if (value == null || value.Trim() == string.Empty)
                    continue;

                markText = value.Trim();
                mark = ParseMark(markText);
                return true;
            }

            return false;
        }

        public static string GetPostedMarkTextByQuestionId(HttpRequest request, int questionId)
        {
            decimal mark;
            string markText;
            if (TryGetPostedMarkByQuestionId(request, questionId, out mark, out markText))
                return markText;

            return string.Empty;
        }

        private static string FindRowPrefixByHiddenField(HttpRequest request, string hiddenFieldName, string fieldValue)
        {
            foreach (string key in request.Form.AllKeys)
            {
                if (string.IsNullOrEmpty(key))
                    continue;

                if (key.IndexOf(hiddenFieldName) < 0)
                    continue;

                if (request.Form[key] != fieldValue)
                    continue;

                return GetFormKeyRowPrefix(key);
            }

            return string.Empty;
        }

        private static string GetFormKeyRowPrefix(string formKey)
        {
            if (string.IsNullOrEmpty(formKey))
                return string.Empty;

            int lastDollar = formKey.LastIndexOf('$');
            if (lastDollar <= 0)
                return formKey;

            return formKey.Substring(0, lastDollar + 1);
        }

        private static decimal ParseMark(string markText)
        {
            decimal markValue;
            if (decimal.TryParse(
                markText.Replace(',', '.'),
                NumberStyles.Any,
                CultureInfo.InvariantCulture,
                out markValue))
            {
                return markValue;
            }

            return 0;
        }
    }
}

