public void CaptureStudentMarks(Dictionary<int, string> marks)
{
    if (marks == null)
        return;

    foreach (RepeaterItem item in rptList.Items)
    {
        if (item.ItemType != ListItemType.Item && item.ItemType != ListItemType.AlternatingItem)
            continue;

        HiddenField hidQuestionID = item.FindControl("hidQuestionID") as HiddenField;
        if (hidQuestionID == null)
            continue;

        int questionId;
        if (!int.TryParse(hidQuestionID.Value, out questionId) || questionId <= 0)
            continue;

        decimal mark;
        string markText;
        if (EthicFormPostHelper.TryGetPostedMarkByQuestionId(Page.Request, questionId, out mark, out markText)
            && markText != string.Empty)
        {
            marks[questionId] = markText;
            continue;
        }

        PollPart.Answer uAnswer = item.FindControl("uAnswer") as PollPart.Answer;
        if (uAnswer == null)
            continue;

        string fallbackMarkText = uAnswer.GetStudentMarkText();
        if (fallbackMarkText != string.Empty)
            marks[questionId] = fallbackMarkText;
    }
}

